const attendance = $json.attendance_rate;
const lateMarks = $json.late_marks;
const absentDays = $json.absent_days;

const output =
($json.actual / $json.target) * 100;

const quality =
$json.quality_score;

let score =
(attendance * 0.4) +
(output * 0.4) +
(quality * 0.2);

score -= lateMarks * 1.5;
score -= absentDays * 2;

score = Math.max(0, Math.min(100, score));

const risk = 100 - score;

return [{
json:{
...$json,
reliability_score:score,
attrition_risk:risk
}
}];

