const attendance =
$input.item.json.attendancePercent || 0;

const productivity =
$input.item.json.productivityScore || 0;

const quality =
$input.item.json.qualityScore || 0;

const incidents =
$input.item.json.incidentCount || 0;

const tenure =
$input.item.json.tenureMonths || 0;

const safetyScore =
Math.max(0,100 - (incidents * 20));

const tenureScore =
Math.min(100,(tenure / 12) * 100);

const finalScore =
(attendance * 0.25) +
(productivity * 0.25) +
(quality * 0.20) +
(safetyScore * 0.15) +
(tenureScore * 0.15);

return [{
json:{
...$input.item.json,
attendance,
productivity,
quality,
safetyScore,
tenureScore,
finalScore
}
}];

